public sealed class EnvironmentKeyRing : ISecretKeyRing
{
    public string CurrentKeyId => "2026-10";

    public bool TryGetKey(string keyId, [NotNullWhen(true)] out byte[]? key)
    {
        var text = Environment.GetEnvironmentVariable($"SECRET_KEY_{keyId}");
        key = text is null ? null : System.Convert.FromBase64String(text);
        return key is not null;
    }
}

public static void Register(IServiceCollection services) => services.AddOSSecretKeyRing<EnvironmentKeyRing>();

